"""Original chapter 4: measured R03/R04 evidence and limitations."""
from chapter_helpers import *
b=Book(4,'4장 웹 침투와 지속성');s=b.section;q=b.query;c=b.cmd
s(b.title,
 p('웹 요청에 대한 403 응답이 이어지다가 200 응답과 큰 전송량이 나타났다. 다른 서버에서는 업로드 폴더에 PHP 파일이 추가되고 웹 서버가 셸을 실행한 기록이 이어졌다. 첫 사례에서는 응답의 변화, 두 번째 사례에서는 서버 내부의 후속 동작을 조사한다.'),
 pic('assets/illustrations/chapter04-web-request.png','그림 4-1  웹 요청과 응답 확인',78),
 p('R03은 neobank의 웹 요청, R04는 mediforum의 파일·프로세스·계정 기록이다. 두 라운드는 별개의 사례로 유지한다. 완료 조건은 요청의 응답 변화와 호스트 내부의 실행 흔적을 구분하고, 각 사례에서 확보한 사실·추가 증거·대응 순서를 조사표로 정리하는 것이다.'))
s('4.1 두 사례를 별도로 준비한다',
 p('kt66 Ubuntu VM 호스트에서 교재 폴더로 이동한다. cd ~/hack_ir_book_3, git status --short를 차례로 입력하고 수정 중인 파일이 없으면 git pull --ff-only로 갱신한다. Python 3, 별도 강의 코드 사본과 2장에서 확인한 indexer 연결을 사용한다.'),
 tab(['항목','R03','R04'],[['관찰 대상','neobank 웹 요청','mediforum 지속성'],['seed','303','404'],['전체 문서','83,944건','102,273건'],['배경 / 시나리오','82,454 / 1,490','101,276 / 997'],['전용 인덱스','book3-r03-ch04','book3-r04-ch04']],[32,47.5,47.5]),
 p('두 자료의 기간은 2026-08-03 00:00 이상부터 11-01 00:00 미만까지 KST 90일이다. prepare_round.py는 강의 코드에서 이벤트를 만들고 시간순으로 저장한다. --source는 별도 코드 폴더, --round는 사례, --anchor는 끝 경계, --days는 기간, --scale은 배경 규모, --run-id는 전용 실행 이름, --out은 새 출력 폴더이다. 역슬래시(\\)로 한 명령을 다음 줄에 이어 쓴다.'),
 c(1,'python3 tools/prepare_round.py \\\n  --source ../hack_ir_with_wazuh_source/purple-agg \\\n  --round r03 --anchor 2026-11-01 --days 90 \\\n  --scale 0.005 --run-id ch04 --out build/r03-ch04','R03 자료를 새 폴더에 생성한다.','이미 존재하는 출력 폴더에서는 중단한다. 이전 manifest를 확인하고 실행 이름을 구분한다.','total 83944를 확인한다.'),
 c(2,'python3 tools/check_dataset.py build/r03-ch04','R03의 해시·기간·순서·건수를 검사한다.','인수는 생성한 폴더이다. 파일을 수정했다면 적재 전에 변경 원인을 확인한다.','status pass, events 83944를 확인한다.'),
 c(3,'python3 tools/prepare_round.py \\\n  --source ../hack_ir_with_wazuh_source/purple-agg \\\n  --round r04 --anchor 2026-11-01 --days 90 \\\n  --scale 0.005 --run-id ch04 --out build/r04-ch04','R03 검사를 마친 뒤 R04 자료를 생성한다.','라운드와 출력 폴더를 함께 바꾼다. 두 자료의 사건을 합치지 않도록 폴더를 분리한다.','total 102273을 확인한다.'),
 c(4,'python3 tools/check_dataset.py build/r04-ch04','R04 파일을 검사한다.','생성 조건과 파일 해시는 해당 폴더의 manifest.json에 있다.','status pass, events 102273을 확인한다.'))
s('4.2 전용 자료를 적재하고 검색 범위를 고정한다',
 p('기존 인덱스의 소멸·재생성·건수 감소가 보이면 다른 집필 작업이 끝날 때까지 적재를 기다린다. 안정 상태를 확인한 다음 두 적재 명령을 순서대로 실행한다. 10.20.32.110은 이 환경에서 확인한 indexer 컨테이너 주소이며 자신의 2장 확인 결과로 바꾼다.'),
 c(5,'python3 tools/load_dataset.py build/r03-ch04 \\\n  --url https://10.20.32.110:9200 \\\n  --user admin --insecure','검사한 R03을 새 인덱스에 적재한다.','--url은 indexer, --user는 인증 계정이다. 암호는 실행 뒤 입력한다. --insecure는 자체 서명 인증서 실습용이다. 신뢰할 CA가 있으면 --ca-cert 경로를 사용한다.','created와 count가 모두 83944이다. 기존 인덱스 오류가 나면 중복 적재하지 말고 소유 정보부터 확인한다.'),
 c(6,'python3 tools/load_dataset.py build/r04-ch04 \\\n  --url https://10.20.32.110:9200 \\\n  --user admin --insecure','R03 적재 확인 후 R04를 적재한다.','입력 폴더의 manifest가 전용 인덱스 이름을 정한다. 다른 라운드 폴더와 혼동하지 않는다.','created와 count가 모두 102273이다.'),
 steps('Windows 브라우저에서 자신의 kt66 VM의 HTTPS 5601 주소로 접속한다. 메뉴의 Indexer management → Dev Tools를 연다.','examples/chapter04의 .http 파일을 본문 조회 ID에 맞춰 입력한다. 복사가 끝나고 JSON의 마지막 닫는 중괄호(})까지 들어갔는지 확인한다.','실행할 요청 안에 커서를 놓고 삼각형 버튼 또는 Ctrl+Enter를 누른다. 200 OK, timed_out: false, _shards.failed: 0을 확인한다.'),
 p('모든 조회에 인덱스 이름과 기간을 명시했다. 01~05는 R03, 06~12는 R04이다. track_total_hits: true는 선택 문서의 정확한 건수를 요청한다. size: 0은 원문 목록 대신 집계만 받는 설정이다. 적재된 rule 필드는 생성기가 붙인 값이며 manager가 실제 규칙을 평가한 경보와 구분한다.'))
s('4.3 차단 기록에서 서비스와 출발지를 고른다',
 p('WAF는 웹 요청을 검사해 정책에 맞지 않는 요청을 차단하거나 기록하는 장치·소프트웨어이다. 이 자료의 ModSecurity 원문은 Access denied with code 403이라는 차단 동작을 담는다. decoder.name의 modsecurity는 이 로그 종류를 구분한다. 웹 접근 원문은 web-accesslog이며 같은 요청을 다른 관점에서 기록한다.'),
 q(1,'WAF 기록을 출발지와 서비스로 묶는다.','sources의 Terms는 출발지 상위 3개, sites는 그 출발지의 서비스 상위 3개이다. data.vhost로 차단 대상 서비스를 읽는다.','전체 WAF 기록은 532건이다. 218.136.73.91의 516건은 모두 neobank.kt66.lab이다.'),
 p('동일 요청이 WAF 기록과 웹 접근 기록에 각각 남을 수 있다. 두 건을 더해 공격 요청 두 번으로 세지 않는다. 현재 WAF 원문의 agent.name은 web이고 대상 서비스는 data.vhost에 있다. 다른 디코더와 호스트를 연결할 때 이 역할을 먼저 확인한다.'),
 q(2,'neobank의 같은 출발지에서 403·200·500을 함께 센다.','blocked·ok·error는 한 출발지 버킷 안의 조건별 부분집합이다. blocked 내림차순으로 후보를 고른다. 세 조건 외 응답도 전체 doc_count에 포함된다.','218.136.73.91은 전체 974건, 403 516건, 200 362건, 500 24건이다.'),
 p('516 + 362 + 24 = 902로 전체 974건보다 72건 적다. 나머지는 401·404 응답이다. 200은 요청에 대해 성공 응답을 보냈다는 뜻이며 로그인 페이지·빈 결과도 포함할 수 있다. 500은 서버 처리 중 오류가 발생한 응답이다. SQL 실행 여부는 애플리케이션 오류·DB 감사 기록과 대조한다. 같은 IP를 여러 이용자가 공유할 수 있으므로 세션·계정·요청 식별자가 있으면 함께 확보한다.'))
s('4.4 응답 크기와 요청 내용을 함께 확인한다',
 p('data.bytes는 이 생성기의 웹 접근 원문에서 HTTP 상태 코드 다음에 기록된 응답 크기이다. 요청 크기나 디스크 파일 크기와 구분한다. data.duration_ms는 생성기가 추가한 처리 시간 값이며, 해당 full_log 문자열에는 처리 시간 항목이 없다.'),
 q(3,'history 경로의 최대·평균·합계 응답 크기를 비교한다.','prefix는 /api/history로 시작하는 URL을 선택한다. maximum·average·total은 각각 max·avg·sum이다. 응답 크기 최댓값으로 출발지를 정렬한다.','후보의 886건에서 최대 5,189,279바이트, 평균 약 85,516바이트, 합계 75,767,426바이트이다.'),
 p('최대는 평균의 약 60.7배이다. 합계에는 평소 응답과 오류 응답도 함께 들어 있다. 75,767,426바이트를 그대로 개인정보 유출량으로 적지 말고 큰 응답의 요청·콘텐츠 종류·본문과 승인된 내려받기를 확인한다. 같은 데이터가 반복 전송되었는지도 구분한다.'),
 q(5,'1,000,000바이트 이상인 후보 요청의 원문을 읽는다.','gte는 이상 조건이다. timestamp 오름차순으로 첫 3건을 반환한다. _source는 확인할 필드만 표시한다.','일치 문서는 24건이다. 첫 시각은 10월 28일 16:40:51.202+0900, 응답 200, 2,089,744바이트, 7,478ms이다.'),
 p('data.url에는 주석 문자열과 SQL 키워드, acct_no·owner·balance·ssn 같은 열 이름, LIMIT 구간이 들어 있다. 이 값은 요청에 담긴 입력이다. 응답 본문에 실제로 해당 열이 포함되었는지, DB에서 어떤 조회가 실행되었는지 확보해 조사표에 기록한다. 원문 URL을 서버에 다시 보내는 실습은 수행하지 않는다.'))
s('4.5 응답 변화의 시간 범위를 좁힌다',
 p('90일의 403과 200이 한 버킷에 함께 있다는 결과는 발생 순서를 보여 주지 않는다. 집중 활동일인 10월 28일로 기간을 줄이고 10분씩 묶어 응답 구성을 읽는다.'),
 q(4,'10월 28일 후보의 응답 코드를 시간순으로 비교한다.','fixed_interval: 10m은 고정 10분 간격이다. time_zone은 +09:00이며 key_as_string은 버킷 시작 시각이다. min_doc_count: 1은 이벤트가 있는 칸만 반환한다.','선택 문서는 930건이다. 14:40~15:10 버킷에는 403이, 15:30~16:00에는 200과 500이, 16:40 이후에는 큰 응답을 포함한 200이 나타난다.'),
 tab(['버킷 시작(KST)','주요 응답과 건수'],[['14:00','200 24, 401 8, 404 64'],['14:40 / 14:50','403 84 / 173'],['15:00 / 15:10','403 171 / 52'],['15:30','200 88, 500 4'],['16:40 / 16:50 / 17:00','200 12 / 11 / 1']],[44,83]),
 p('14:00에도 200이 있다. 이를 첫 우회 성공 시각이라고 정하지 않는다. 그때의 경로는 사전 탐색 대상일 수 있다. 15:30 버킷의 원문에서 입력 문자열·응답 본문·WAF 정책 버전을 확인해 변화의 원인을 조사한다. 버킷 시작 15:30:00과 첫 요청의 실제 시각도 구분한다.'),
 p('반복 조회를 경보로 만들 때는 같은 서비스·출발지·시간 창을 조건에 포함한다. 403 20회와 200 20회가 같은 창에 있어도 순서는 별도로 검증해야 한다. 승인된 진단과 계정 공유를 고려해 검토할 후보를 반환하고, 실제 차단은 영향 범위를 확인한 뒤 결정한다.'))
s('4.6 업로드 파일에서 실행 흔적을 찾는다',
 p('이제 R04로 전환한다. 웹셸은 웹 요청을 통해 서버의 명령 실행 등을 제공하는 스크립트이다. FIM은 파일 무결성 감시로, 지정한 경로의 추가·수정·삭제를 기록한다. 이 자료의 rule.id 554는 파일 추가를 표현하며 경로는 syscheck.path에 저장된다.'),
 pic('assets/figures/chapter04-evidence-chain.png','그림 4-2  R04의 요청·파일·실행 기록 연결'),
 q(6,'업로드 폴더에 추가된 파일을 확장자로 나눈다.','wildcard의 별표(*)는 길이가 다른 문자열과 일치한다. 첫 조건은 /var/www 아래 uploads 경로이고, extensions의 filters는 확장자별 부분집합이다.','전체 12건 중 jpg 2, png 5, pdf 4, php 1건이다.'),
 pic('assets/screenshots/chapter04/extensions-detail.png','화면 4-1  업로드 파일 확장자별 추가 건수',90),
 p('이번 배율에서는 정상 형식의 업로드가 11건뿐이다. 강의의 수천 건 규모와 혼동하지 않는다. 파일 이름이 .php로 끝나는 사실에서 실행 여부까지 확인하려면 웹 서버의 실행 정책과 프로세스 기록을 연결해야 한다. 업무상 PHP 업로드를 허용했는지도 확인한다.'),
 p('프로세스는 실행 중인 프로그램이다. auditd는 Linux 감사 이벤트를 기록하는 서비스이며 실행 파일·명령을 조사할 때 사용한다. cron은 예약된 시각에 작업을 시작하는 서비스이다. 이 자료는 두 종류의 실행을 미리 정규화한 필드로 제공한다.'),
 q(7,'감사 기록에서 부모 프로세스와 실행 파일의 조합을 찾는다.','data.audit.parent는 이 학습 자료의 부모 실행 파일, data.audit.exe는 실행 대상이다. 부모별 최대 5개 실행 파일을 표시한다.','apache2와 /bin/sh 조합은 25건이다. cron과 /usr/bin/php는 12,157건, cron과 /tmp/.x/update.sh는 937건이다.'),
 p('웹 요청에 따라 외부 프로그램을 실행하는 CGI나 운영 스크립트에서도 셸이 실행될 수 있다. 서비스의 승인된 프로세스 조합과 명령 내용을 비교한다. 실제 audit 원문에서는 프로세스 식별자(PID)·부모 식별자(PPID), 시스템 호출(SYSCALL)·프로그램 실행(EXECVE) 레코드를 확보해 부모와 실행 파일을 재구성한다. 이 생성기의 parent·exe·auid는 미리 정규화한 학습 필드이며 full_log 한 줄에서 모두 복원되는 값이 아니다.'))
s('4.7 경로·호스트·시각으로 연결한다',
 q(8,'mediforum의 업로드 PHP 호출 출발지를 찾는다.','agent.name을 mediforum으로 고정하고 /uploads/*.php*와 일치하는 웹 원문을 선택한다. urls는 질의 문자열까지 포함한 고유 URL 수이다.','70.246.138.5가 25회 호출했고 고유 URL은 21개이다. 최초 9월 22일 22:11:24.964, 최종 10월 25일 09:39:19.193 KST이다.'),
 p('고유 URL 21개는 웹셸 파일 21개가 아니다. 같은 파일 뒤에 붙은 ?c= 값이 다르면 별도 URL이 된다. 파일 경로와 질의 문자열을 분리해 기록한다. min·max의 value_as_string이 Z로 끝나면 UTC이므로 KST 표시와 비교할 때 9시간 차이를 반영한다.'),
 q(9,'9월 22일의 파일 추가와 처음 두 실행을 시각순으로 읽는다.','should의 후보 조건은 출발지·부모 프로세스·PHP 파일이다. minimum_should_match: 1은 그중 하나 이상을 필수로 한다. 바깥 filter로 호스트와 날짜를 고정한다.','38건 중 처음 6건을 반환한다. /upload 요청, PHP 파일 추가, ?c=id 요청, sh -c id 실행 순서가 보인다.'),
 tab(['KST 시각','관찰 기록'],[['22:08:10.000','/upload 요청'],['22:08:10.400','uploads/202609/av_7731.php 추가'],['22:11:24.964','같은 파일의 ?c=id 호출'],['22:11:25.014','apache2가 /bin/sh 실행'],['22:13:55.714 / .764','다음 웹 요청과 셸 실행']],[43,84]),
 p('절대 경로 /var/www/mediforum/uploads/202609/av_7731.php와 웹 경로 /uploads/202609/av_7731.php는 문서 루트 설정을 통해 연결한다. 같은 호스트의 시각이 0.05초 차이로 짝을 이룬 것은 생성기 설계이다. 운영 로그에서는 요청 ID·프로세스 ID·세션과 시계 오차를 확인해 연결 강도를 판단한다.'))
s('4.8 계정과 예약 작업의 후속 흔적을 읽는다',
 p('지속성은 최초 접근 뒤에도 다시 실행하거나 접속할 수 있는 수단을 유지하는 것이다. 계정, 공개 키, 예약 작업, 부팅 시 실행 항목을 나누어 조사한다. 먼저 업로드와 셸 실행 뒤에 어떤 파일·계정 이벤트가 이어졌는지 읽는다.'),
 q(10,'계정 생성과 /etc·/root 파일 변경을 시각순으로 확인한다.','같은 mediforum 호스트에서 세 조건 중 하나 이상을 만족한 원문을 선택한다. size: 10은 이번 7건을 모두 담는다.','sysupdate 생성 1건과 파일 이벤트 6건이다. /etc/cron.d/sysupdate 추가는 22:34:51.550이다.'),
 tab(['대상','확인할 역할'],[['sysupdate, /etc/passwd·group·shadow','계정·그룹·인증 정보 변경'],['/etc/cron.d/sysupdate','예약 작업 등록'],['/root/.ssh/authorized_keys','root 접속용 공개 키'],['/etc/rc.local','부팅 시 실행 항목과 서비스 활성 상태']],[55,72]),
 p('파일 변경 기록에서 변경 내용을 확보하고 승인된 관리 작업과 비교한다. authorized_keys의 변경은 실제 접속 여부와 나누어 기록한다. rc.local은 해당 환경에서 실행되도록 구성되어 있는지 확인한다. FIM 시각만으로 예약 작업·키 접속·부팅 실행이 모두 성공했다고 쓰지 않는다.'),
 q(11,'cron의 실행 파일별 횟수와 처음·마지막 관측을 비교한다.','hosts는 agent.name의 고유 수로, 서비스 도메인 수와 구분한다.','/tmp/.x/update.sh는 한 호스트에서 937건이다. 최초 9월 22일 23:00:01.972, 최종 10월 31일 23:00:00.890 KST이다.'),
 q(12,'의심 작업의 연속 실행 시각을 확인한다.','부모·실행 파일·호스트를 모두 고정하고 처음 6건을 반환한다. data.audit.auid는 이번 자료에서 root 문자열이다. 실제 Linux 감사 식별자의 형식·의미는 원문과 디코더 설정으로 확인한다.','처음 여섯 기록은 23시·0시·1시·2시·3시·4시의 약 1~2초 뒤에 나타난다.'),
 p('예약 작업을 등록한 명령 문자열에는 */10 * * * *가 들어 있다. 분 칸의 */10은 매시간 0·10·20·30·40·50분이고 나머지 별표는 모든 값을 뜻한다. 그러나 이 학습 파일의 실행 이벤트는 약 3,600초 간격이다. 조사표에 “설정 문자열은 10분, 관측 기록은 약 1시간”으로 함께 적는다. 생성 코드가 매시간 이벤트를 추가한 불일치이다. 이 차이를 실제 수집 누락이나 50분의 장애로 해석하지 않는다.'))
s('4.9 대응 판단과 실패 확인',
 tab(['사례','먼저 보존할 자료','대응 판단과 확인'],[['R03','요청·응답 본문, WAF 정책, DB 감사·오류 기록','취약 경로·계정·허용 범위 확인 뒤 제한; 정상 요청과 차단 기록 비교'],['R04','업로드 파일 해시·복사본, 프로세스·연결·계정·예약 설정','격리 범위 결정 뒤 실행 경로·키·계정 정리; 정상 서비스와 재실행 여부 확인']],[20,53,54]),
 p('실제 조사에서는 파일을 이동·삭제하기 전에 원문과 분석 사본의 해시, 수집 시각, 담당자를 기록한다. 계정 잠금이나 예약 작업 제거는 서비스 의존 관계를 확인하고 승인된 대응 범위에서 수행한다. 합성 인덱스만 있는 이번 실습에서는 조사표에 조치 대상과 성공 기준을 작성한다. 생성 로그의 경로를 실제 kt66 파일로 간주해 삭제하거나 계정을 잠그지 않는다.'),
 p('조회가 0건이면 R03/R04 인덱스 구분, 과거 검색 기간, agent.name과 data.vhost의 역할, 경로 대소문자를 차례로 확인한다. 400 JSON 오류이면 복사한 요청의 마지막 중괄호까지 입력되었는지 확인한다. 쿼리 입력이 끝나기 전에 실행하지 않는다. 집계는 나오지만 문서가 안 보이면 size: 0 설정을 확인하고 원문 조회 번호로 전환한다.'),
 p('실제 규칙을 평가할 때는 정규화된 인덱스와 manager 입력을 구분한다. R03의 집계 모니터 원본은 설명에 “같은 사이트”를 쓰지만 실제 조건은 서비스별 묶음 없이 IP를 센다. 서비스와 시간 창을 명시한 후보 조회부터 점검한다. Wazuh 규칙의 조건·빈도·관측 필드와 실제 경보를 대조한 뒤 적용한다.'))
s('4.10 결과 보존과 원상복구',
 p('examples/chapter04/investigation.csv를 사례별로 한 부씩 작성한다. 인덱스·manifest 해시·조회 번호·기간·원문 _id·관찰 사실·추가 증거·대응 기준을 기록한다. Dev Tools의 결과를 저장한 다음 다른 작업으로 전환한다. 전용 인덱스는 다시 검토할 때까지 보존할 수 있다.'),
 p('자료를 제거해야 할 때는 정확한 전용 인덱스의 _meta.book3와 로컬 manifest를 먼저 비교한다. round·expected_events·bulk_sha256이 맞는지 확인하고 원문과 결과를 보관한 뒤 아래 순서로 한 사례씩 제거한다. DELETE는 저장된 검색 자료를 제거하는 요청이다.'),
 code('GET /book3-r03-ch04/_mapping'),code('DELETE /book3-r03-ch04'),code('GET /book3-r03-ch04/_count'),
 code('GET /book3-r04-ch04/_mapping'),code('DELETE /book3-r04-ch04'),code('GET /book3-r04-ch04/_count'),
 p('삭제 응답 acknowledged: true와 이후 index_not_found_exception을 확인한다. 다른 라운드나 공용 wazuh-alerts 인덱스는 선택하지 않는다. 별도로 만든 인덱스 패턴이 있으면 그 전용 패턴만 제거하고 이전 검색 범위로 돌아간다.'))
s('확인 문제',
 p('1. 같은 출발지에서 403과 200이 함께 나왔을 때 우회 시각을 조사하려면 무엇을 더 확인해야 하는가?'),
 p('2. URL 21개와 PHP 파일 1개가 함께 나오는 이유는 무엇인가?'),
 p('3. 예약식은 10분인데 실행 기록이 한 시간 간격이면 조사표에 어떻게 기록하는가?'),
 h('해설'),
 p('1. 서비스·경로·입력·실제 응답 내용과 시각을 좁혀 WAF 정책·애플리케이션·DB 기록에 대조한다. 10분 버킷의 시작 시각은 개별 요청 시각과 구분한다.'),
 p('2. 같은 경로 뒤의 질의 문자열이 바뀌면 고유 URL 값이 달라진다. 문서 루트와 경로를 확인해 실제 파일 수를 따로 구한다.'),
 p('3. 설정값과 관측값을 함께 적는다. 이 사례에서는 생성기의 시간 간격 불일치이며, 운영 환경에서는 실제 설정·실행 기록·수집 상태를 확보해 원인을 조사한다.'))
